39	/// Check if Rooftop Storm is on the battlefield and provides a {0} alternative cost
40	/// for a Zombie creature spell cast by the given player.
41	fn rooftop_storm_applies(state: &GameState, registry: &CardRegistry, card_id: CardId, caster: PlayerId) -> bool {
42	    // Check if the spell is a Zombie creature spell.
43	    let is_zombie_creature = registry.card_data(card_id).map(|d| {
44	        d.card_types.contains(&CardType::Creature)
45	            && d.subtypes.iter().any(|s| s == "Zombie")
46	    }).unwrap_or(false);
47	    if !is_zombie_creature {
48	        return false;
49	    }
50	    // Check if the caster controls a Rooftop Storm on the battlefield.
51	    state.objects.values().any(|o| {
52	        o.zone == Zone::Battlefield
53	            && o.controller == caster
54	            && o.name == "Rooftop Storm"
55	    })
56	}
57	
58	/// Compute the effective mana cost of a spell after applying cost reduction effects.
59	/// Returns a reduced ManaCost (generic portion lowered, colored requirements unchanged).
60	pub fn effective_spell_cost(state: &GameState, registry: &CardRegistry, card_id: CardId, base_cost: &ManaCost, caster: PlayerId) -> ManaCost {
61	    use crate::types::{ContinuousEffect, SpellFilter};
62	
63	    // Check if the card has a custom cost modification (e.g., Blasphemous Act).
64	    if let Some(behavior) = registry.get(card_id) {
65	        if let Some(modified) = behavior.modified_cost(state, registry) {
66	            return modified;
67	        }
68	    }
69	
70	    let card_data = registry.card_data(card_id);
71	    let is_creature = card_data.as_ref()
72	        .map(|d| d.card_types.contains(&CardType::Creature))
73	        .unwrap_or(false);
74	    let subtypes: Vec<String> = card_data.as_ref()
75	        .map(|d| d.subtypes.clone())
76	        .unwrap_or_default();
77	
78	    // Gather all ReduceCost effects from permanents the caster controls.
79	    let mut total_reduction: u32 = 0;
